mapper.select:
SELECT id, content, embedding, metadata::text AS metadata, created_at
FROM ai_knowledge_chunk
WHERE embedding IS NOT NULL
  AND (1 - (embedding <=> #{queryVector, typeHandler=com.example.langchain4j.common.util.VectorTypeHandler})) >= #{minScore}
ORDER BY embedding <=> #{queryVector, typeHandler=com.example.langchain4j.common.util.VectorTypeHandler}
LIMIT #{topK}
